package com.sumedha.commerce.user.dto.request; import com.sumedha.commerce.user.enums.AddressType; import jakarta.validation.*; import org.junit.jupiter.api.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*;
class UserRequestValidationTest {static Validator v;@BeforeAll static void init(){v=Validation.buildDefaultValidatorFactory().getValidator();} boolean bad(Object x){return !v.validate(x).isEmpty();}@Test void validatesProfiles(){assertFalse(bad(new CreateProfileRequest("A","B",null,null,LocalDate.now())));assertTrue(bad(new CreateProfileRequest(" ","B",null,null,null)));assertTrue(bad(new CreateProfileRequest("A"," ",null,null,null)));assertTrue(bad(new CreateProfileRequest("a".repeat(101),"B",null,null,null)));assertTrue(bad(new UpdateProfileRequest("A","B","x".repeat(41),"x".repeat(2049),LocalDate.now().plusDays(1))));}@Test void validatesAddressAndPreferences(){assertFalse(bad(new CreateAddressRequest(AddressType.SHIPPING,"A","L",null,"C",null,"P","se",null,false)));assertTrue(bad(new CreateAddressRequest(null,"A"," ",null," ",null," ","1",null,false)));assertTrue(bad(new UpdateAddressRequest(AddressType.BOTH,"x".repeat(151),"x".repeat(201),"x".repeat(201),"x".repeat(101),null,"x".repeat(31),"123",null,false)));assertFalse(bad(new UpdatePreferencesRequest("en","sek",false,true)));assertTrue(bad(new UpdatePreferencesRequest("x","12",false,true)));}}
